import os
from flask import Flask, request, send_file, abort

app = Flask(__name__)
ASSET_ROOT = os.path.abspath("/var/www/app/assets/")

@app.route('/assets/theme')
def get_theme_asset():
    theme_name = request.args.get('theme', 'default')
    asset_path = request.args.get('path', 'style.css')

    # Fix: Ensure the path is relative and check if the resulting absolute path is within ASSET_ROOT
    safe_path = os.path.join(ASSET_ROOT, theme_name, asset_path.lstrip("/"))
    if not os.path.abspath(safe_path).startswith(ASSET_ROOT):
        abort(403)

    return send_file(safe_path)

