from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse
from pathlib import Path

app = FastAPI()
BACKUP_BASE = Path("/mnt/backups/").resolve()

@app.get("/download/backup")
async def download_backup(partition: str, filename: str):
    # Fix: Resolve the path and check if the base is still the prefix
    try:
        # Ensure we treat inputs as relative
        full_path = (BACKUP_BASE / partition.lstrip("/") / filename.lstrip("/")).resolve()
        if not full_path.is_relative_to(BACKUP_BASE):
            raise HTTPException(status_code=403)
        return FileResponse(str(full_path))
    except Exception:
        raise HTTPException(status_code=400)

from flask import Flask, request, send_from_directory, abort
import os

app = Flask(__name__)
CONFIG_ROOT = os.path.abspath("/mnt/user_configs/")

@app.route('/config/load')
def load_config():
    user_id = request.args.get('uid', 'default')
    filename = request.args.get('file', 'settings.json')

    # Fix: Ensure user_id is a simple identifier and use abspath check
    if not user_id.isalnum():
        abort(400)

    user_space = os.path.abspath(os.path.join(CONFIG_ROOT, user_id))
    target_file = os.path.abspath(os.path.join(user_space, filename))

    if not target_file.startswith(user_space):
        abort(403)

    return send_from_directory(user_space, filename)

