from fastapi import FastAPI, HTTPException
import os

app = FastAPI()
WORK_DIR = os.path.abspath("/tmp/processing/")

@app.get("/process/status")
async def check_status(job_id: str):
    # Fix: Ensure job_id doesn't contain separators and verify final path
    if os.path.sep in job_id:
        raise HTTPException(status_code=400)

    full_path = os.path.abspath(os.path.join(WORK_DIR, job_id, "status.json"))
    if not full_path.startswith(WORK_DIR):
        raise HTTPException(status_code=403)

    return {"status": "found" if os.path.exists(full_path) else "missing"}

